package com.example.rokidgeminisecretary;
import org.json.*;import java.io.*;import java.util.*;
final class MaintenanceSearch {
 static JSONObject search(MainActivity c,String query,JSONObject filter)throws Exception{String type=filter.optString("type");if(!type.matches("|conversation|meeting|reading|inbox|memo|continuation|photo|memory|task"))throw new IOException("検索種別が不正です");JSONObject base=UnifiedRecords.search(c,query,new JSONObject(filter.toString()).put("type",type.matches("photo|memory|task")?"":type));JSONArray rows=base.getJSONArray("items"),issues=base.getJSONArray("issues");ArrayList<JSONObject> all=new ArrayList<>();if(!type.matches("photo|memory|task"))for(int i=0;i<rows.length();i++)all.add(rows.getJSONObject(i));JSONArray extra=new JSONArray();try{File[] photos=RecorderPhotoStore.root(c).listFiles((d,n)->n.matches("[0-9]{13}-[a-f0-9-]{36}\\.gcm"));if(photos==null)throw new IOException();Arrays.sort(photos,(a,b)->b.getName().compareTo(a.getName()));if(photos.length>500)issues.put("写真は直近500件の保存メタデータのみ");for(int i=0;i<Math.min(500,photos.length);i++){File f=photos[i];JSONObject meta=RecorderPhotoStore.metadata(f);StringBuilder body=new StringBuilder();for(String key:new String[]{"caption","description","text","answer","readText"})if(meta.has(key))body.append(meta.optString(key)).append("\n");extra.put(UnifiedRecords.item("photo",f.getName().replace(".gcm",""),Long.parseLong(f.getName().substring(0,13)),"写真 "+f.getName().substring(0,13),body.toString()));}}catch(Exception e){issues.put("写真メタデータの一部を取得できません");}try{JSONArray memories=new DynamicMemorySync(c).state().getJSONArray("entries");for(int i=0;i<memories.length();i++){JSONObject row=memories.getJSONObject(i);extra.put(UnifiedRecords.item("memory","dynamic-"+row.optString("id"),row.optLong("at"),row.optString("topic"),row.optString("content")));}memories=ImportedMemory.read(c);for(int i=0;i<memories.length();i++){JSONObject row=memories.getJSONObject(i);extra.put(UnifiedRecords.item("memory","imported-"+row.optString("id"),row.optLong("importedAt"),"取込記憶",row.optString("summary")));}}catch(Exception e){issues.put("記憶の一部を取得できません");}try{JSONArray tasks=MeetingTaskBoard.list(c);for(int i=0;i<tasks.length();i++){JSONObject row=tasks.getJSONObject(i);extra.put(UnifiedRecords.item("task",row.getString("id"),row.getLong("at"),row.getString("title"),row.optString("assignee")+" "+row.optString("due")+" "+row.optString("excerpt")).put("pending",row.optString("state").equals("pending")));}}catch(Exception e){issues.put("会議タスクを取得できません");}try{JSONArray anchors=RecordAnchors.search(c,query,issues);for(int i=0;i<anchors.length();i++)extra.put(anchors.get(i));}catch(Exception e){issues.put("文字起こし検索を取得できません");}long from=filter.optLong("from",0),until=filter.optLong("until",Long.MAX_VALUE);int matched=type.matches("photo|memory|task")?0:base.getInt("matched");for(int i=0;i<extra.length();i++){JSONObject row=extra.getJSONObject(i);if((type.isEmpty()||type.equals(row.getString("type")))&&row.optLong("at")>=from&&row.optLong("at")<=until&&(!filter.optBoolean("pending")||row.optBoolean("pending"))&&RecordSearchPolicy.matches(row.optString("title")+" "+row.optString("body"),query)){all.add(row);matched++;}}all.sort((a,b)->Long.compare(b.optLong("at"),a.optLong("at")));JSONArray out=new JSONArray();for(int i=0;i<Math.min(50,all.size());i++)out.put(all.get(i));return base.put("items",out).put("matched",matched).put("scope",base.getString("scope")+" 追加：直近500写真の保存済み説明（新規OCRなし）、スマホ記憶キャッシュ・取込記憶、会議タスク。文字起こしは直近20会議・各先頭30ブロック・合計2MBまで、ブロック単位の概算時刻。日時不明の記憶は日付指定時に対象外です。");}
 private MaintenanceSearch(){}
}
